package dev.trentdb.storage; import dev.trentdb.storage.format.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.io.*;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class DuckDbRowGroupHeaderReaderTest{@TempDir Path d;
@Test void zeroGroups(){try(var m=file("zero",join(stats(),le(0)))){var h=read(m,MetaBlockPointer.of(0,0,0)).read();assertEquals(List.of(),h.statistics().columns());assertEquals(List.of(),h.groups());}}
@Test void multipleGroupsAndPackedPointers(){long data=MetaBlockPointer.of(42,7,0).blockPointer(),delete=MetaBlockPointer.of(9,3,0).blockPointer();try(var m=file("multiple",join(stats(),le(2),group(0,3,List.of(pointer(data,300),pointer(0,0)),List.of(pointer(delete,17))),group(3,2,List.of(),List.of())))){var h=read(m,MetaBlockPointer.of(0,0,0)).read().groups();assertEquals(2,h.size());var first=h.get(0);assertEquals(0,first.rowStart());assertEquals(3,first.tupleCount());assertEquals(new DuckDbTableEntryEnvelope.MetaPointer(data,300),first.dataPointers().get(0));assertEquals(42,first.dataPointers().get(0).blockId());assertEquals(7,first.dataPointers().get(0).subBlockIndex());assertEquals(new DuckDbTableEntryEnvelope.MetaPointer(0,0),first.dataPointers().get(1));assertEquals(new DuckDbTableEntryEnvelope.MetaPointer(delete,17),first.deletePointers().get(0));assertEquals(3,h.get(1).rowStart());assertEquals(2,h.get(1).tupleCount());assertEquals(List.of(),h.get(1).dataPointers());assertEquals(List.of(),h.get(1).deletePointers());}}
@Test void rejectsCountsBeyondJavaBounds(){try(var m=file("group-count",join(stats(),le((long)Integer.MAX_VALUE+1)))){var e=assertThrows(StorageFormatException.class,()->read(m,MetaBlockPointer.of(0,0,0)).read());assertEquals("DuckDB row group count exceeds supported bound",e.getMessage());}var body=new ByteArrayOutputStream();field(body,100);u(body,0);field(body,101);u(body,1);field(body,102);u(body,(long)Integer.MAX_VALUE+1);try(var m=file("pointer-count",join(stats(),le(1),body.toByteArray()))){var e=assertThrows(StorageFormatException.class,()->read(m,MetaBlockPointer.of(0,0,0)).read());assertEquals("DuckDB row group pointer count exceeds supported bound",e.getMessage());}}
@Test void rejectsTruncatedRowGroupAtMetadataBoundary(){byte[] truncated=join(stats(),le(1),fbytes(100),ubytes(0));int size=MetadataBlockLayout.metadataBlockSize(StorageFormat.DEFAULT_BLOCK_SIZE);try(var m=fileAt("truncated",truncated,size-truncated.length)){var e=assertThrows(StorageFormatException.class,()->read(m,MetaBlockPointer.of(0,0,size-truncated.length)).read());assertEquals("No more data remains in the DuckDB metadata chain",e.getMessage());}}
@Test void readsFields104Through107AndNativePrecedence(){var b=new ByteArrayOutputStream();field(b,100);u(b,0);field(b,101);u(b,1);field(b,102);u(b,0);field(b,103);u(b,0);field(b,104);b.write(1);field(b,105);u(b,2);u(b,44);u(b,77);field(b,106);b.write(1);field(b,107);u(b,2);u(b,Long.MIN_VALUE|4);u(b,99);term(b);try(var m=file("metadata",join(stats(),le(1),b.toByteArray()))){var h=read(m,MetaBlockPointer.of(0,0,0)).read().groups().get(0);assertFalse(h.hasMetadataBlocks());assertEquals(List.of(),h.extraMetadataBlocks());assertTrue(h.hasPerColumnMetadataBlocks());assertEquals(List.of(new DuckDbRowGroupHeaders.PerColumnMetadataBlock(true,4),new DuckDbRowGroupHeaders.PerColumnMetadataBlock(false,99)),h.perColumnMetadataBlocks());}}@Test void rejectsOversizedExtraMetadataBlockList(){var b=new ByteArrayOutputStream();field(b,100);u(b,0);field(b,101);u(b,1);field(b,102);u(b,0);field(b,103);u(b,0);field(b,104);b.write(0);field(b,105);u(b,(long)Integer.MAX_VALUE+1);try(var m=file("metadata-overflow",join(stats(),le(1),b.toByteArray()))){var e=assertThrows(StorageFormatException.class,()->read(m,MetaBlockPointer.of(0,0,0)).read());assertEquals("DuckDB row group extra metadata block count exceeds supported bound",e.getMessage());}}
private DuckDbRowGroupHeaderReader read(SingleFileBlockManager m,MetaBlockPointer p){return new DuckDbRowGroupHeaderReader(m,p,List.of());}private SingleFileBlockManager file(String n,byte[] p){return fileAt(n,p,8);}private SingleFileBlockManager fileAt(String n,byte[] p,int o){var x=d.resolve(n+".duckdb");try(var w=SingleFileBlockManager.create(x,new byte[16])){var b=new byte[w.usableBlockSize()];for(int i=0;i<8;i++)b[i]=(byte)(MetaBlockPointer.INVALID_BLOCK_POINTER>>>8*i);System.arraycopy(p,0,b,o,p.length);w.writeBlock(0,b);}return SingleFileBlockManager.openMetadataReadOnly(x);}private static byte[] stats(){return join(fbytes(100),ubytes(0),fbytes(65535));}private static byte[] group(long start,long count,List<byte[]> data,List<byte[]> del){var b=new ByteArrayOutputStream();field(b,100);u(b,start);field(b,101);u(b,count);field(b,102);list(b,data);field(b,103);list(b,del);term(b);return b.toByteArray();}private static byte[] pointer(long packed,long offset){var b=new ByteArrayOutputStream();if(packed!=0){field(b,100);u(b,packed);}if(offset!=0){field(b,101);u(b,offset);}term(b);return b.toByteArray();}private static void list(ByteArrayOutputStream b,List<byte[]> ps){u(b,ps.size());for(var p:ps)b.writeBytes(p);}private static byte[] le(long v){var b=new byte[8];for(int i=0;i<8;i++)b[i]=(byte)(v>>>8*i);return b;}private static byte[] join(byte[]... ps){var b=new ByteArrayOutputStream();for(var p:ps)b.writeBytes(p);return b.toByteArray();}private static byte[] fbytes(int id){var b=new ByteArrayOutputStream();field(b,id);return b.toByteArray();}private static byte[] ubytes(long v){var b=new ByteArrayOutputStream();u(b,v);return b.toByteArray();}private static void field(ByteArrayOutputStream b,int id){b.write(id);b.write(id>>>8);}private static void term(ByteArrayOutputStream b){field(b,65535);}private static void u(ByteArrayOutputStream b,long v){do{int n=(int)(v&127);v>>>=7;b.write(v==0?n:n|128);}while(v!=0);}}
